// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _keepAddress, address caller) public {
        // Ensure the caller is not an approved logger
        vm.assume(!c.approvedToLog(caller));
        // Call logCreated from an unapproved caller
        vm.prank(caller);
        bool result = c.logCreated(_keepAddress);
        assertTrue(result == false);
    }
}

